package cli

// `mus completion install` writes a shell-completion script to the
// conventional location for the user's shell. Saves the user from looking
// up the right directory for each shell.

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spf13/cobra"
)

// bashCompletionPolyfill is prepended to the bash completion script
// generated by cobra. cobra's script (both V1 and V2) calls
// `_get_comp_words_by_ref` — a helper from the external
// bash-completion package. On systems where that package isn't
// installed (HPC nodes, stripped-down containers, macOS without
// brew bash-completion), tab triggers
// `_get_comp_words_by_ref: command not found` and completion is
// broken.
//
// The polyfill defines a minimal _get_comp_words_by_ref ONLY when
// the function is not already provided. If bash-completion IS
// installed, the polyfill is a no-op. Handles the only invocation
// cobra makes:
//
//   _get_comp_words_by_ref -n EXCLUDES cur prev words cword
//
// where -n EXCLUDES (e.g. `-n =:`) lists characters to ignore as
// word separators. Our polyfill silently accepts and ignores -n
// because bash's COMP_WORDS array already gives us the cobra-
// friendly splitting; the result is correct for the way cobra
// uses these vars.
const bashCompletionPolyfill = `# Self-contained polyfill for the bash-completion helper
# _get_comp_words_by_ref, added by mus. Only defined when missing
# (i.e. when the bash-completion package isn't installed). On
# systems where bash-completion IS installed, this block is inert.
if ! declare -F _get_comp_words_by_ref >/dev/null 2>&1; then
    _get_comp_words_by_ref() {
        # Skip leading "-n EXCLUDES" pairs; we don't need them
        # because COMP_WORDS already preserves '=' / ':' in the
        # current word, which is what cobra cares about.
        while [[ $# -ge 2 && "$1" == "-n" ]]; do
            shift 2
        done
        # Remaining args are variable names cobra wants filled.
        local __mus_name
        for __mus_name in "$@"; do
            case "$__mus_name" in
                cur)   printf -v cur   '%s' "${COMP_WORDS[COMP_CWORD]}" ;;
                prev)  printf -v prev  '%s' "${COMP_WORDS[COMP_CWORD-1]}" ;;
                words) words=("${COMP_WORDS[@]}") ;;
                cword) cword=$COMP_CWORD ;;
            esac
        done
    }
fi

`

// newCompletionInstallCmd attaches an `install` subcommand to the
// auto-generated `mus completion` group. cobra synthesises the
// `completion bash/zsh/fish/powershell` siblings; we add `install` for
// fire-and-forget setup.
func newCompletionInstallCmd(root *cobra.Command) *cobra.Command {
	var shell, dest string
	cmd := &cobra.Command{
		Use:   "install",
		Short: "write a completion script to the conventional path for your shell",
		Long: "Auto-detects your shell from $SHELL (override with --shell), picks the\n" +
			"right XDG / dotfile location, and writes the completion script there.\n" +
			"Equivalent to running `mus completion <shell> > <path>` but without\n" +
			"having to remember the path.\n\n" +
			"Falls back to the parent of $0 if neither $XDG_*_HOME nor $HOME work.",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runCompletionInstall(root, shell, dest, cmd.OutOrStdout())
		},
	}
	cmd.Flags().StringVar(&shell, "shell", "",
		"shell to install for (bash | zsh | fish); default: detect from $SHELL")
	cmd.Flags().StringVar(&dest, "dest", "",
		"explicit destination file (overrides the conventional path)")
	return cmd
}

func runCompletionInstall(root *cobra.Command, shellFlag, destFlag string, stdout interface{ Write([]byte) (int, error) }) error {
	sh := shellFlag
	if sh == "" {
		sh = detectShell()
	}
	if sh == "" {
		return fmt.Errorf("could not detect shell from $SHELL; pass --shell bash | zsh | fish")
	}
	sh = strings.ToLower(filepath.Base(sh))

	path := destFlag
	if path == "" {
		var err error
		path, err = completionPath(sh)
		if err != nil {
			return err
		}
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("creating %s: %w", filepath.Dir(path), err)
	}

	// Generate the completion script. For bash we use the V2 stream
	// generator so we can prepend the bash-completion polyfill in
	// front of the cobra-generated body; the other shells use cobra's
	// file generator directly.
	var genErr error
	switch sh {
	case "bash":
		genErr = writeBashCompletionFile(root, path)
	case "zsh":
		genErr = root.GenZshCompletionFile(path)
	case "fish":
		genErr = root.GenFishCompletionFile(path, true)
	default:
		return fmt.Errorf("unsupported shell %q (supported: bash, zsh, fish)", sh)
	}
	if genErr != nil {
		return fmt.Errorf("generating %s completion: %w", sh, genErr)
	}

	fmt.Fprintf(stdout, "✓ installed %s completion to %s\n", sh, path)
	switch sh {
	case "bash":
		fmt.Fprintf(stdout, "  Reload your shell, or run:  source %s\n", path)
	case "zsh":
		fmt.Fprintf(stdout,
			"  Reload your shell. If completions don't show up, ensure %s\n"+
				"  is in your $fpath (e.g. add to .zshrc: fpath=(%s $fpath) and run `compinit`).\n",
			filepath.Dir(path), filepath.Dir(path))
	case "fish":
		fmt.Fprintf(stdout, "  Fish reloads completions automatically.\n")
	}
	return nil
}

// writeBashCompletionFile writes a self-contained bash completion
// script for `root` to `path`: the bash-completion polyfill (no-op
// when bash-completion is installed) followed by cobra's V2
// completion body. Atomic write — temp-file + rename.
func writeBashCompletionFile(root *cobra.Command, path string) error {
	var buf bytes.Buffer
	buf.WriteString(bashCompletionPolyfill)
	if err := root.GenBashCompletionV2(&buf, true); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".mus-completion.tmp.*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	if _, err := tmp.Write(buf.Bytes()); err != nil {
		tmp.Close()
		os.Remove(tmpName)
		return err
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpName)
		return err
	}
	if err := os.Rename(tmpName, path); err != nil {
		os.Remove(tmpName)
		return err
	}
	return nil
}

// detectShell returns the shell base name from $SHELL (bash, zsh, fish, …)
// or "" if it can't be determined.
func detectShell() string {
	s := os.Getenv("SHELL")
	if s == "" {
		return ""
	}
	return filepath.Base(s)
}

// completionPath returns the conventional install location for a shell's
// completion script for the running user. Honours XDG_DATA_HOME and
// XDG_CONFIG_HOME when set; otherwise falls back to ~/.local/share (bash,
// zsh) or ~/.config (fish).
func completionPath(sh string) (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	switch sh {
	case "bash":
		base := os.Getenv("XDG_DATA_HOME")
		if base == "" {
			base = filepath.Join(home, ".local", "share")
		}
		return filepath.Join(base, "bash-completion", "completions", "mus"), nil
	case "zsh":
		base := os.Getenv("XDG_DATA_HOME")
		if base == "" {
			base = filepath.Join(home, ".local", "share")
		}
		return filepath.Join(base, "zsh", "site-functions", "_mus"), nil
	case "fish":
		base := os.Getenv("XDG_CONFIG_HOME")
		if base == "" {
			base = filepath.Join(home, ".config")
		}
		return filepath.Join(base, "fish", "completions", "mus.fish"), nil
	}
	return "", fmt.Errorf("unsupported shell %q", sh)
}
